export const customerQuestionStats = () => {
  const total = CUSTOMER_QUESTION_CASES.length;
  const implemented = CUSTOMER_QUESTION_CASES.filter((c) => c.implemented).length;
  return {
    total,
    implemented,
    backlog: total - implemented,
  };
}
